-- REFERENCE OUTLINE ONLY.
create table if not exists creator_interop_organs (id uuid primary key default gen_random_uuid(), organization_id uuid not null, organ_type text not null, charter_version text not null, status text not null, created_at timestamptz not null default now());
create table if not exists creator_interop_decisions (id uuid primary key default gen_random_uuid(), organ_id uuid not null, decision_type text not null, status text not null, policy_version text not null, source_manifest_id uuid not null, idempotency_key text not null unique, effective_at timestamptz, created_at timestamptz not null default now());
create table if not exists creator_interop_headquarters_agreements (id uuid primary key default gen_random_uuid(), organization_id uuid not null, host_jurisdiction text not null, status text not null, agreement_hash text not null, effective_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists creator_interop_privilege_schedules (id uuid primary key default gen_random_uuid(), headquarters_agreement_id uuid not null, beneficiary_class text not null, functional_scope text not null, territory text not null, waiver_authority text not null, alternative_remedy text not null, status text not null default 'not_applicable', created_at timestamptz not null default now());
